    /// <summary>The (LEFT, RIGHT) horizontal skyline pair for an accidental kind,
    /// in the glyph's own frame (X from the glyph origin, Y centred on the note).</summary>
    public static (HorizontalSkyline Left, HorizontalSkyline Right) AccidentalSkylinePair(string kind) => kind switch
    {
        "sharp" => (AccSkyPairSharp.Left, AccSkyPairSharp.Right),
        "flat" => (AccSkyPairFlat.Left, AccSkyPairFlat.Right),
        "natural" => (AccSkyPairNatural.Left, AccSkyPairNatural.Right),
        "doubleSharp" => (AccSkyPairDoubleSharp.Left, AccSkyPairDoubleSharp.Right),
        "doubleFlat" => (AccSkyPairDoubleFlat.Left, AccSkyPairDoubleFlat.Right),
        // naturals-as-fallback: an unknown kind draws the natural sign.
        _ => (AccSkyPairNatural.Left, AccSkyPairNatural.Right),
    };

    /// <summary>The raw outline skyline pair of accidentals.leftparen /
    /// accidentals.rightparen, in each paren glyph's own frame. A courtesy
    /// accidental's stencil embeds these at its LILC edges (padding 0), and the
    /// runtime composition mirrors that placement.
    /// LILYPOND-REF: lily/accidental.cc:33-43 parenthesize.</summary>
    public static (HorizontalSkyline Left, HorizontalSkyline Right) AccidentalParenSkylinePair(bool leftParen) =>
        leftParen ? (AccSkyPairLeftParen.Left, AccSkyPairLeftParen.Right)
                  : (AccSkyPairRightParen.Left, AccSkyPairRightParen.Right);

    /// <summary>The (DOWN, UP) VERTICAL skyline of a clef glyph, as raw sign-framed
    /// buildings in the glyph's own frame (X from the glyph origin, Y from the line the
    /// glyph sits on). Raw rather than a built skyline because every seat wants it at a
    /// different x, y and staff size, and a <c>VerticalSkyline</c> is mutable.
    /// LILYPOND-REF: scm/define-grobs.scm:902-927 <c>grob::always-vertical-skylines-from-stencil</c>
    /// is what the Clef declares, hence
    /// lily/stencil-integral.cc:562 add_named_glyph_segments and
    /// lily/freetype.cc:174-202 Path_interpreter, run by ly_FT_add_outline_to_skyline.</summary>
    public static (double[] Down, double[] Up) ClefVerticalSkylineQuads(string kind) => kind switch
    {
        "F" => (ClefSkyFD, ClefSkyFU),
        "C" => (ClefSkyCD, ClefSkyCU),
        // The G clef is the fallback for the same reason it is in ClefInk.
        _ => (ClefSkyGD, ClefSkyGU),
    };

    /// <summary>The (DOWN, UP) VERTICAL skyline of one fetaText dynamic letter, as raw
    /// sign-framed buildings in the glyph's own frame (X from the letter's PEN origin, Y
    /// from the baseline) — default when the char is not one of the seven the encoding
    /// draws dynamics from (the caller falls back, as TryGetDynamicInk does). A label's
    /// profile is these letters composed at pen positions = advance + kern
    /// (<c>DynamicLetter*Advance</c> / <see cref="DynamicLetterKern"/>).
    /// LILYPOND-REF: scm/define-grobs.scm:1446 DynamicText <c>grob::always-vertical-skylines-from-stencil</c>,
    /// :1412-1413 DynamicLineSpanner <c>from-element-stencils</c>; the outline walk is
    /// lily/stencil-integral.cc:562 add_named_glyph_segments and
    /// lily/freetype.cc:174-202 Path_interpreter, as for the clefs above.</summary>
    public static (double[] Down, double[] Up) DynamicLetterVerticalSkylineQuads(char c) => c switch
    {
        'f' => (DynSkyFD, DynSkyFU),
        'm' => (DynSkyMD, DynSkyMU),
        'n' => (DynSkyND, DynSkyNU),
        'p' => (DynSkyPD, DynSkyPU),
        'r' => (DynSkyRD, DynSkyRU),
        's' => (DynSkySD, DynSkySU),
        'z' => (DynSkyZD, DynSkyZU),
        _ => default,
    };

    /// <summary>The (DOWN, UP) VERTICAL skyline of the trill line's repeating element,
    /// as raw sign-framed buildings in the glyph's own frame (X from the glyph origin, Y
    /// from its baseline — the caller centres it, as <c>align_to (Y_AXIS, CENTER)</c>
    /// does, and steps copies by the LILC width).
    /// LILYPOND-REF: lily/line-interface.cc:48-108 make_trill_line repeats
    /// scripts.trill_element along the line; scm/define-grobs.scm:4085 TrillSpanner
    /// <c>grob::unpure-vertical-skylines-from-stencil</c> makes that run the grob's own
    /// profile, which side-position-interface.cc:353-358 and
    /// axis-group-interface.cc:770-773 both measure against.</summary>
    public static (double[] Down, double[] Up) TrillElementVerticalSkylineQuads()
        => (ScrSkyTrillElementD, ScrSkyTrillElementU);

    /// <summary>GPOS pair kern between two adjacent fetaText dynamic letters, in staff
    /// spaces (negative pulls the second letter in; 0 for every pair the font does not
    /// kern). Pango applies exactly these when it shapes a dynamic string, so a label's
    /// pen positions are advances plus these — measured against LilyPond in
    /// audit/lp-geometry/probes/dynamic-text-x.ly (every pair the font's sign and
    /// magnitude; the per-glyph shaping quantisation stays a named residual family).</summary>
    public static double DynamicLetterKern(char first, char second) => (first, second) switch
    {
        ('f', 'f') => -0.152000,
        ('m', 'f') => -0.116000,
        ('m', 'p') => 0.232000,
        ('n', 'f') => -0.116000,
        ('n', 'p') => 0.232000,
        ('r', 'f') => 0.116000,
        ('s', 'p') => 0.348000,
        ('z', 'p') => 0.232000,
        _ => 0.0,
    };

    private static readonly (HorizontalSkyline Left, HorizontalSkyline Right) AccSkyPairSharp =
        (HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Left, AccSkySharpL),
         HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Right, AccSkySharpR));
    private static readonly (HorizontalSkyline Left, HorizontalSkyline Right) AccSkyPairFlat =
        (HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Left, AccSkyFlatL),
         HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Right, AccSkyFlatR));
    private static readonly (HorizontalSkyline Left, HorizontalSkyline Right) AccSkyPairNatural =
        (HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Left, AccSkyNaturalL),
         HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Right, AccSkyNaturalR));
    private static readonly (HorizontalSkyline Left, HorizontalSkyline Right) AccSkyPairDoubleSharp =
        (HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Left, AccSkyDoubleSharpL),
         HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Right, AccSkyDoubleSharpR));
    private static readonly (HorizontalSkyline Left, HorizontalSkyline Right) AccSkyPairDoubleFlat =
        (HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Left, AccSkyDoubleFlatL),
         HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Right, AccSkyDoubleFlatR));
    private static readonly (HorizontalSkyline Left, HorizontalSkyline Right) AccSkyPairLeftParen =
        (HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Left, AccSkyLeftParenL),
         HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Right, AccSkyLeftParenR));
    private static readonly (HorizontalSkyline Left, HorizontalSkyline Right) AccSkyPairRightParen =
        (HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Left, AccSkyRightParenL),
         HorizontalSkyline.FromSignedBuildings(HorizontalDirection.Right, AccSkyRightParenR));
}
